code.css:
:root{
  --ink:#23282a;
  --ink-2:#414a4c;
  --muted:#586163;
  --line:#d3d9d4;
  --bg:#f3f5f3;
  --card:#ffffff;
  --moss:#3d6044;
  --moss-deep:#2b4731;
  --paper:#efe9dc;
  --dark:#22282a;
}
*,*::before,*::after{box-sizing:border-box;}
html{-webkit-text-size-adjust:100%;}
body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Hiragino Sans GB','Microsoft YaHei','Noto Sans CJK SC',sans-serif;font-size:16px;line-height:1.65;}
h1,h2,h3{font-family:'Songti SC','STSong','Noto Serif CJK SC','Source Han Serif SC',SimSun,Georgia,serif;font-weight:600;line-height:1.32;margin:0;letter-spacing:.01em;}
h1{font-size:clamp(29px,4.2vw,44px);}
h2{font-size:clamp(21px,2.4vw,27px);}
h3{font-size:18px;}
p{margin:0 0 14px;}
p:last-child{margin-bottom:0;}
a{color:var(--moss);text-decoration:none;border-bottom:1px solid #b7c6b9;}
a:hover{color:var(--moss-deep);border-bottom-color:var(--moss-deep);}
a:focus-visible{outline:2px solid var(--moss-deep);outline-offset:3px;}
img{display:block;max-width:100%;height:auto;}
ul,ol,dl{margin:0;}
[id]{scroll-margin-top:88px;}
.wrap{max-width:1120px;margin:0 auto;padding:0 24px;}
.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0;}

.section{padding:42px 0;}
.section h2{margin-bottom:20px;}
.section h3{margin:22px 0 10px;}
.hero{padding:50px 0 8px;}
.hero h1{margin-bottom:16px;}
.page-head{padding:46px 0 8px;}
.page-head h1{margin-bottom:14px;}
.lead{font-size:17px;color:var(--ink-2);max-width:38em;margin:0;}

.site-head{background:var(--card);border-bottom:1px solid var(--line);}
.head-row{display:flex;align-items:center;justify-content:space-between;gap:20px;min-height:64px;}
.brand{display:inline-flex;align-items:center;gap:10px;border-bottom:0;color:var(--ink);}
.brand-bar{display:inline-block;width:6px;height:22px;background:var(--moss);}
.brand-name{font-family:'Songti SC','STSong',SimSun,Georgia,serif;font-size:19px;font-weight:600;letter-spacing:.06em;}
.site-nav{display:flex;align-items:center;gap:24px;}
.site-nav a{color:var(--ink-2);border-bottom:1px solid transparent;padding:4px 0;font-size:15px;}
.site-nav a:hover{color:var(--moss);border-bottom-color:var(--moss);}

.atlas{display:grid;grid-template-columns:1fr 1fr;gap:30px 40px;}
.atlas-main{grid-column:1 / -1;display:grid;grid-template-columns:1.15fr 1fr;gap:24px 44px;border-top:2px solid var(--moss);padding-top:20px;}
.atlas-main h3{font-size:24px;margin:0 0 12px;}
.atlas-main h3 a{border-bottom:0;}
.atlas-main h3 a:hover{border-bottom:1px solid var(--moss);}
.atlas-use{color:var(--ink-2);max-width:32em;margin:0;}
.atlas-item{border-top:1px solid var(--line);padding-top:18px;}
.atlas-item h3{font-size:20px;margin:0 0 10px;}
.atlas-item h3 a{border-bottom:0;}
.atlas-item h3 a:hover{border-bottom:1px solid var(--moss);}
.atlas-item figure{margin:16px 0 0;}
.atlas-item img{width:100%;border:1px solid var(--line);}
figure{margin:0;}
figcaption{font-size:12.5px;color:var(--muted);line-height:1.55;margin-top:8px;}

.spec-mini{display:grid;margin:0;}
.spec-mini > div{display:flex;gap:18px;padding:9px 0;border-bottom:1px solid var(--line);font-size:14.5px;}
.spec-mini dt{flex:0 0 82px;color:var(--muted);margin:0;}
.spec-mini dd{margin:0;font-variant-numeric:tabular-nums;}

.timeline{display:grid;max-width:760px;}
.timeline > div{display:flex;gap:26px;padding:11px 0;border-bottom:1px solid var(--line);font-size:15.5px;}
.timeline dt{flex:0 0 92px;color:var(--moss);font-weight:600;font-variant-numeric:tabular-nums;margin:0;}
.timeline dd{margin:0;}

.band{background:var(--dark);color:#eef1ee;padding:44px 0;margin:34px 0;}
.band h2{color:#ffffff;margin-bottom:22px;}
.eq-grid{display:grid;grid-template-columns:1.4fr 1fr;gap:28px 48px;align-items:start;}
.eq-list{list-style:none;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:0 32px;}
.eq-list li{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #3b4446;font-size:15px;color:#e8ede8;}
.eq-list .num{color:#c8d4c9;font-variant-numeric:tabular-nums;}
.eq-note{margin:0;font-size:14.5px;color:#d3dcd4;border-left:2px solid #7f9c85;padding-left:14px;}

.news{list-style:none;padding:0;max-width:820px;}
.news li{display:grid;grid-template-columns:112px 1fr;gap:22px;padding:13px 0;border-bottom:1px solid var(--line);}
.news time{color:var(--moss);font-size:14px;font-variant-numeric:tabular-nums;}
.news p{margin:0;font-size:15.5px;color:var(--ink-2);}

.spec-table{width:100%;border-collapse:collapse;margin:0 0 8px;font-size:15px;}
.spec-table th,.spec-table td{text-align:left;padding:11px 18px 11px 0;border-bottom:1px solid var(--line);vertical-align:top;}
.spec-table th{width:112px;font-weight:500;color:var(--muted);}
.spec-table td{font-variant-numeric:tabular-nums;}

.split{display:grid;grid-template-columns:1.55fr 1fr;gap:28px 48px;align-items:start;}
.duo{display:grid;grid-template-columns:1fr 1fr;gap:28px 48px;align-items:start;}
.split h3:first-child,.duo h3:first-child{margin-top:0;}

.terms{display:grid;margin:0;}
.terms > div{padding:11px 0;border-bottom:1px solid var(--line);}
.terms dt{font-size:13px;color:var(--muted);margin:0 0 3px;}
.terms dd{margin:0;font-size:15.5px;font-variant-numeric:tabular-nums;}

.notice{background:var(--paper);border-left:3px solid var(--moss);padding:18px 22px;}
.notice h3{font-size:16px;margin:0 0 8px;}
.notice p{margin:0;font-size:15px;}

.cases{display:grid;grid-template-columns:1fr 1fr;gap:28px 40px;}
.case{border-top:1px solid var(--line);padding-top:16px;}
.case-wide{grid-column:1 / -1;border-top:2px solid var(--moss);}
.case h3{font-size:19px;margin:0 0 8px;}
.case p{margin:0;font-size:15.5px;color:var(--ink-2);}

.ticks{list-style:none;padding:0;max-width:760px;}
.ticks li{position:relative;padding:9px 0 9px 20px;border-bottom:1px solid var(--line);font-size:15.5px;}
.ticks li::before{content:'';position:absolute;left:0;top:17px;width:7px;height:7px;background:var(--moss);}

.steps{list-style:none;padding:0;counter-reset:step;}
.steps li{counter-increment:step;position:relative;padding:10px 0 10px 36px;border-bottom:1px solid var(--line);font-size:15.5px;}
.steps li::before{content:counter(step);position:absolute;left:0;top:11px;width:24px;height:24px;border:1px solid var(--moss);color:var(--moss);font-size:12.5px;line-height:22px;text-align:center;font-variant-numeric:tabular-nums;}

.compare > div{border-top:2px solid var(--moss);padding-top:16px;}
.compare h3{margin:0 0 10px;font-size:19px;}
.compare p{margin:0;font-size:15.5px;color:var(--ink-2);}

.faq{max-width:800px;}
.faq dt{border-top:1px solid var(--line);padding-top:15px;font-weight:600;font-size:15.5px;}
.faq dd{margin:7px 0 15px;font-size:15.5px;color:var(--ink-2);}

.figure img{width:100%;border:1px solid var(--line);}
.fine{font-size:14px;color:var(--muted);max-width:46em;margin:22px 0 0;}

.site-foot{background:var(--dark);color:#e9eeea;margin-top:46px;padding:34px 0 36px;}
.foot-row{display:flex;justify-content:space-between;align-items:flex-start;gap:28px;}
.foot-name{font-family:'Songti SC','STSong',SimSun,Georgia,serif;font-size:18px;font-weight:600;letter-spacing:.06em;color:#ffffff;margin:0 0 6px;}
.foot-line{margin:0;font-size:14px;color:#c3cdc5;}
.foot-meta p{margin:0 0 6px;font-size:14px;color:#dfe6e0;font-variant-numeric:tabular-nums;}
.foot-meta p:last-child{margin-bottom:0;}

@media (max-width:640px){
  .head-row{gap:10px;min-height:56px;}
  .brand{gap:8px;}
  .brand-bar{width:5px;height:18px;}
  .brand-name{font-size:16px;letter-spacing:.03em;}
  .site-nav{gap:12px;}
  .site-nav a{font-size:14px;}
}

@media (max-width:768px){
  .wrap{padding:0 18px;}
  .hero{padding:34px 0 4px;}
  .page-head{padding:30px 0 4px;}
  .section{padding:26px 0;}
  .band{padding:30px 0;margin:22px 0;}
  .atlas,.atlas-main,.split,.duo,.eq-grid,.eq-list,.cases,.news li{grid-template-columns:1fr;}
  .atlas-main{gap:18px;}
  .atlas-main h3{font-size:22px;}
  .eq-list{gap:0;}
  .timeline > div{flex-direction:column;gap:2px;}
  .timeline dt{flex:none;}
  .news li{gap:4px;}
  .spec-table th{width:84px;}
  .foot-row{flex-direction:column;gap:18px;}
  .site-foot{margin-top:28px;padding:26px 0 28px;}
  .lead{font-size:16px;}
}
